function p({registerIndicator:o,nulls:r}){o({id:"oa-wclprice",name:"WCLPRICE: Weighted Close Price",category:"Price Core",placement:"onchart",inputs:[],plots:[{key:"wclprice",type:"line",title:"WclPrice",style:{color:"#ff5252",lineWidth:2}}],calc(i){const t=new Array(i.length).fill(NaN);for(let e=0;e<i.length;e++){const c=i[e].high,l=i[e].low,n=i[e].close;!Number.isFinite(c)||!Number.isFinite(l)||!Number.isFinite(n)||(t[e]=(c+l+2*n)*.25)}return{wclprice:r(t)}}})}export{p as default};
